import express, { Request, Response } from 'express';
import http from 'http';
import path from 'path';
import fs from 'fs';
import { createServer as createViteServer } from 'vite';
import { WebSocketServer, WebSocket } from 'ws';

const app = express();
const PORT = 3000;

app.use(express.json({ limit: '15mb' }));
app.use(express.urlencoded({ extended: true }));

// Ensure data directory exists
const DB_DIR = path.join(process.cwd(), 'data');
const DB_FILE = path.join(DB_DIR, 'characters.json');
const MATCHES_FILE = path.join(DB_DIR, 'pvp_matches.json');

if (!fs.existsSync(DB_DIR)) {
  fs.mkdirSync(DB_DIR, { recursive: true });
}

function loadCharacters(): any[] {
  try {
    if (fs.existsSync(DB_FILE)) {
      const data = fs.readFileSync(DB_FILE, 'utf-8');
      const parsed = JSON.parse(data);
      if (Array.isArray(parsed)) {
        return parsed;
      }
    }
  } catch (err) {
    console.error('Error reading DB:', err);
  }
  return [];
}

function saveCharacters(chars: any[]) {
  try {
    fs.writeFileSync(DB_FILE, JSON.stringify(chars, null, 2), 'utf-8');
  } catch (err) {
    console.error('Error saving DB:', err);
  }
}

function loadMatchHistory(): any[] {
  try {
    if (fs.existsSync(MATCHES_FILE)) {
      const data = fs.readFileSync(MATCHES_FILE, 'utf-8');
      const parsed = JSON.parse(data);
      if (Array.isArray(parsed)) {
        return parsed;
      }
    }
  } catch (err) {
    console.error('Error reading matches DB:', err);
  }
  return [];
}

function saveMatchHistory(matches: any[]) {
  try {
    fs.writeFileSync(MATCHES_FILE, JSON.stringify(matches, null, 2), 'utf-8');
  } catch (err) {
    console.error('Error saving matches DB:', err);
  }
}

// ==========================================
// CHARACTER REST API
// ==========================================

app.get('/api/characters', (req: Request, res: Response) => {
  const { search, role, element } = req.query;
  let list = loadCharacters();

  if (search) {
    const term = String(search).toLowerCase();
    list = list.filter(
      (c) =>
        c.name?.toLowerCase().includes(term) ||
        c.cardDescription?.toLowerCase().includes(term) ||
        c.tags?.some((t: string) => t.toLowerCase().includes(term))
    );
  }

  if (role && role !== 'all') {
    list = list.filter((c) => c.role === role);
  }

  if (element && element !== 'all') {
    list = list.filter((c) => c.element === element);
  }

  res.json({
    success: true,
    data: list,
    total: list.length,
  });
});

app.get('/api/characters/:id', (req: Request, res: Response) => {
  const { id } = req.params;
  const list = loadCharacters();
  const char = list.find((c) => String(c.id) === String(id));

  if (!char) {
    return res.status(404).json({ success: false, error: 'Персонаж не найден' });
  }

  res.json({
    success: true,
    data: char,
  });
});

app.post('/api/characters', (req: Request, res: Response) => {
  const payload = req.body;
  if (!payload.name || typeof payload.name !== 'string' || !payload.name.trim()) {
    return res.status(400).json({ success: false, error: 'Имя персонажа обязательно' });
  }

  const list = loadCharacters();
  const newId = payload.id ? String(payload.id) : String(Date.now());

  const newChar = {
    id: newId,
    name: payload.name.trim(),
    title: payload.title?.trim() || '',
    cardDescription: payload.cardDescription?.trim() || '',
    imageUrl: payload.imageUrl?.trim() || 'https://images.unsplash.com/photo-1568602471122-7832951cc4c5?w=400&auto=format&fit=crop&q=80',
    tags: Array.isArray(payload.tags) ? payload.tags : [],
    age: Number(payload.age) || 25,
    height: Number(payload.height) || 175,
    role: payload.role || 'Воин',
    element: payload.element || 'Огонь',
    lore: payload.lore?.trim() || '',
    stats: {
      strength: Number(payload.stats?.strength) || 70,
      agility: Number(payload.stats?.agility) || 70,
      intellect: Number(payload.stats?.intellect) || 70,
      defense: Number(payload.stats?.defense) || 70,
      magic: Number(payload.stats?.magic) || 50,
      regeneration: Number(payload.stats?.regeneration) || 60,
      hp: Number(payload.stats?.hp) || 120,
      maxHp: Number(payload.stats?.maxHp) || Number(payload.stats?.hp) || 120,
      mana: Number(payload.stats?.mana) || 60,
      maxMana: Number(payload.stats?.maxMana) || Number(payload.stats?.mana) || 60,
      level: Number(payload.stats?.level) || 1,
    },
    skills: Array.isArray(payload.skills) ? payload.skills : [],
    customStats: Array.isArray(payload.customStats) ? payload.customStats : [],
    connections: Array.isArray(payload.connections) ? payload.connections : [],
    createdAt: Date.now(),
    updatedAt: Date.now(),
  };

  list.unshift(newChar);
  saveCharacters(list);

  res.status(201).json({
    success: true,
    data: newChar,
    message: `Персонаж «${newChar.name}» успешно создан!`,
  });
});

app.patch('/api/characters/:id', (req: Request, res: Response) => {
  const { id } = req.params;
  const list = loadCharacters();
  const index = list.findIndex((c) => String(c.id) === String(id));

  if (index === -1) {
    return res.status(404).json({ success: false, error: 'Персонаж не найден' });
  }

  const existing = list[index];
  const updates = req.body;

  list[index] = {
    ...existing,
    ...updates,
    stats: {
      ...existing.stats,
      ...(updates.stats || {}),
    },
    updatedAt: Date.now(),
  };

  saveCharacters(list);

  res.json({
    success: true,
    data: list[index],
    message: 'Персонаж успешно обновлен',
  });
});

app.delete('/api/characters/:id', (req: Request, res: Response) => {
  const { id } = req.params;
  let list = loadCharacters();
  const exists = list.some((c) => String(c.id) === String(id));

  if (!exists) {
    return res.status(404).json({ success: false, error: 'Персонаж не найден' });
  }

  list = list.filter((c) => String(c.id) !== String(id));
  saveCharacters(list);

  res.json({
    success: true,
    message: `Персонаж удален`,
  });
});

app.get('/api/pvp/matches', (req: Request, res: Response) => {
  const matches = loadMatchHistory();
  res.json({ success: true, data: matches });
});

// ==========================================
// REAL-TIME MULTIPLAYER PVP ENGINE (WEBSOCKETS)
// ==========================================

interface ExtendedWebSocket extends WebSocket {
  userId?: string;
  userName?: string;
  userAvatar?: string;
  roomId?: string;
  isAlive?: boolean;
}

interface ServerPvpPlayer {
  id: string;
  name: string;
  avatarUrl: string;
  title?: string;
  isHost: boolean;
  isReady: boolean;
  selectedCharacterIds: string[];
  charactersData: any[];
  faction: 'player' | 'enemy';
  color: string;
  ws?: ExtendedWebSocket;
}

interface ServerPvpRoom {
  id: string;
  title: string;
  mode: '1vs1' | '3vs3';
  status: 'waiting' | 'selecting' | 'in_battle' | 'finished';
  maxPlayers: number;
  players: ServerPvpPlayer[];
  mapId: string;
  mapWidth: number;
  mapHeight: number;
  tiles: Record<string, string>;
  obstacles: Record<string, string>;
  characters: any[];
  activeCharacterId?: string;
  activePlayerId?: string;
  turnOrderQueue: string[]; // array of character IDs
  turnIndex: number;
  turnNumber: number;
  roundNumber: number;
  turnTimer?: NodeJS.Timeout;
  turnTimeRemaining: number;
  turnTimeMax: number;
  winnerPlayerId?: string;
  winnerName?: string;
  createdAt: number;
  startedAt?: number;
  finishedAt?: number;
  recentActionLog: Array<{
    id: string;
    text: string;
    timestamp: number;
    color?: string;
  }>;
}

const pvpRooms = new Map<string, ServerPvpRoom>();

function broadcastToRoom(room: ServerPvpRoom, message: any, excludeWs?: WebSocket) {
  const raw = JSON.stringify(message);
  for (const p of room.players) {
    if (p.ws && p.ws.readyState === WebSocket.OPEN && p.ws !== excludeWs) {
      try {
        p.ws.send(raw);
      } catch (err) {
        console.error('WS send error to player', p.name, err);
      }
    }
  }
}

function broadcastRoomsList(targetWs?: WebSocket) {
  const summaries = Array.from(pvpRooms.values()).map((r) => ({
    id: r.id,
    title: r.title,
    mode: r.mode,
    status: r.status,
    playerCount: r.players.length,
    maxPlayers: r.maxPlayers,
    hostName: r.players[0]?.name || 'Игрок',
    hostAvatar: r.players[0]?.avatarUrl || '',
    createdAt: r.createdAt,
  }));

  const msg = JSON.stringify({
    type: 'ROOMS_LIST',
    payload: { rooms: summaries },
  });

  if (targetWs && targetWs.readyState === WebSocket.OPEN) {
    targetWs.send(msg);
  }
}

function serializeRoomForClient(room: ServerPvpRoom): any {
  return {
    id: room.id,
    title: room.title,
    mode: room.mode,
    status: room.status,
    maxPlayers: room.maxPlayers,
    players: room.players.map((p) => ({
      id: p.id,
      name: p.name,
      avatarUrl: p.avatarUrl,
      title: p.title,
      isHost: p.isHost,
      isReady: p.isReady,
      selectedCharacterIds: p.selectedCharacterIds,
      charactersData: p.charactersData,
      faction: p.faction,
      color: p.color,
    })),
    mapId: room.mapId,
    mapData: {
      id: room.mapId,
      name: 'Боевая Арена Разлома',
      width: room.mapWidth,
      height: room.mapHeight,
      defaultTile: 'stone_ruins',
      tiles: room.tiles,
      obstacles: room.obstacles,
      characters: room.characters,
      createdAt: room.createdAt,
      updatedAt: Date.now(),
    },
    activeCharacterId: room.activeCharacterId,
    activePlayerId: room.activePlayerId,
    turnNumber: room.turnNumber,
    roundNumber: room.roundNumber,
    turnTimeRemaining: room.turnTimeRemaining,
    turnTimeMax: room.turnTimeMax,
    characters: room.characters,
    winnerPlayerId: room.winnerPlayerId,
    winnerName: room.winnerName,
    createdAt: room.createdAt,
    startedAt: room.startedAt,
    finishedAt: room.finishedAt,
    recentActionLog: room.recentActionLog,
  };
}

function createPvpArenaMap(width = 24, height = 24) {
  const tiles: Record<string, string> = {};
  const obstacles: Record<string, string> = {};

  for (let x = 0; x < width; x++) {
    for (let y = 0; y < height; y++) {
      if ((x === 0 || x === width - 1 || y === 0 || y === height - 1)) {
        tiles[`${x},${y}`] = 'void';
      } else if (
        (x >= 8 && x <= 15 && y >= 8 && y <= 15) ||
        (x === 11 && y === 12) || (x === 12 && y === 11)
      ) {
        tiles[`${x},${y}`] = 'stone_ruins';
      } else if ((x + y) % 2 === 0) {
        tiles[`${x},${y}`] = 'cobblestone';
      } else {
        tiles[`${x},${y}`] = 'stone_ruins';
      }
    }
  }

  // Symmetrical obstacles (decorative columns & barricades)
  const obstaclePositions = [
    { x: 7, y: 7, type: 'torch_pillar' },
    { x: 16, y: 7, type: 'torch_pillar' },
    { x: 7, y: 16, type: 'torch_pillar' },
    { x: 16, y: 16, type: 'torch_pillar' },
    { x: 11, y: 8, type: 'rubble' },
    { x: 12, y: 15, type: 'rubble' },
    { x: 8, y: 12, type: 'barrel' },
    { x: 15, y: 11, type: 'barrel' },
    { x: 11, y: 11, type: 'chest' },
    { x: 12, y: 12, type: 'chest' },
  ];

  for (const obs of obstaclePositions) {
    obstacles[`${obs.x},${obs.y}`] = obs.type;
  }

  return { tiles, obstacles, width, height };
}

function getPvpSpawnCoordinates(playerIndex: number, slotIndex: number, mode: '1vs1' | '3vs3', mapWidth = 24, mapHeight = 24) {
  if (playerIndex === 0) {
    // Player 1 (Blue / Bottom-Left Flank)
    if (mode === '1vs1') {
      return { x: 5, y: 5, facing: 'right' as const };
    }
    const spawns = [
      { x: 4, y: 5, facing: 'right' as const },
      { x: 5, y: 4, facing: 'right' as const },
      { x: 6, y: 6, facing: 'right' as const },
    ];
    return spawns[slotIndex] || spawns[0];
  } else {
    // Player 2 (Red / Top-Right Flank)
    if (mode === '1vs1') {
      return { x: mapWidth - 6, y: mapHeight - 6, facing: 'left' as const };
    }
    const spawns = [
      { x: mapWidth - 5, y: mapHeight - 6, facing: 'left' as const },
      { x: mapWidth - 6, y: mapHeight - 5, facing: 'left' as const },
      { x: mapWidth - 7, y: mapHeight - 7, facing: 'left' as const },
    ];
    return spawns[slotIndex] || spawns[0];
  }
}

function startTurnTimer(room: ServerPvpRoom) {
  if (room.turnTimer) {
    clearInterval(room.turnTimer);
    room.turnTimer = undefined;
  }

  room.turnTimeRemaining = room.turnTimeMax;

  room.turnTimer = setInterval(() => {
    if (room.status !== 'in_battle') {
      if (room.turnTimer) clearInterval(room.turnTimer);
      return;
    }

    room.turnTimeRemaining -= 1;

    if (room.turnTimeRemaining <= 0) {
      // Auto-pass turn on timeout
      handleServerEndTurn(room, room.activeCharacterId || '');
    }
  }, 1000);
}

function startMatchInRoom(room: ServerPvpRoom) {
  room.status = 'in_battle';
  room.startedAt = Date.now();
  room.turnNumber = 1;
  room.roundNumber = 1;

  const arena = createPvpArenaMap(24, 24);
  room.mapWidth = arena.width;
  room.mapHeight = arena.height;
  room.tiles = arena.tiles;
  room.obstacles = arena.obstacles;
  room.characters = [];

  // Spawn characters for each player
  room.players.forEach((player, pIdx) => {
    const charsData = player.charactersData && player.charactersData.length > 0
      ? player.charactersData
      : player.selectedCharacterIds.map((id) => ({ id, name: `Герой ${id}` }));

    charsData.forEach((charTemplate, slotIdx) => {
      const spawn = getPvpSpawnCoordinates(pIdx, slotIdx, room.mode, arena.width, arena.height);
      const stats = charTemplate.stats || {};
      const maxHp = Number(stats.hp || stats.maxHp || 120);
      const maxMana = Number(stats.mana || stats.maxMana || 60);
      const speed = Math.max(1, Number(stats.speed || 5));
      const ap = Math.max(1, Number(stats.ap || 3));

      const placedChar = {
        id: `pvp_char_${player.id}_${charTemplate.id || slotIdx}_${Date.now()}`,
        characterId: charTemplate.id,
        name: charTemplate.name || `Боец ${player.name}`,
        avatarUrl: charTemplate.imageUrl || charTemplate.avatarUrl || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=200',
        spriteUrl: charTemplate.spriteUrl || '',
        stars: charTemplate.stars || 3,
        rarity: charTemplate.rarity || 'Редкий',
        role: charTemplate.role || 'Воин',
        faction: pIdx === 0 ? 'player' : 'enemy',
        ownerId: player.id,
        ownerName: player.name,
        playerColor: player.color,
        x: spawn.x,
        y: spawn.y,
        facing: spawn.facing,
        currentHp: maxHp,
        maxHp: maxHp,
        currentMana: maxMana,
        maxMana: maxMana,
        currentAp: ap,
        maxAp: ap,
        currentMpPoints: speed,
        maxMpPoints: speed,
        speed: speed,
        stats: {
          ...stats,
          baseAttack: Number(stats.baseAttack || 75),
          armor: Number(stats.armor || stats.defense || 50),
          magicArmor: Number(stats.magicArmor || 40),
          critChance: Number(stats.critChance || 5),
          evasion: Number(stats.evasion || 5),
          accuracy: Number(stats.accuracy || 95),
          agility: Number(stats.agility || 50),
          strength: Number(stats.strength || 50),
          intellect: Number(stats.intellect || 50),
          speed: speed,
          ap: ap,
        },
        skills: Array.isArray(charTemplate.skills) && charTemplate.skills.length > 0
          ? charTemplate.skills
          : [
              {
                id: 'pvp_strike',
                name: 'Мощный удар',
                type: 'active',
                cost: '1 ОД',
                description: 'Наносит 120% физического урона врагу.',
                formula: 'ATK * 1.2',
                targetType: 'single_enemy',
                range: 1,
              },
            ],
      };

      room.characters.push(placedChar);
    });
  });

  // Sort turn order by Agility / Speed descending
  room.characters.sort((a, b) => {
    const agiA = Number(a.stats?.agility || a.speed || 0);
    const agiB = Number(b.stats?.agility || b.speed || 0);
    return agiB - agiA;
  });

  room.turnOrderQueue = room.characters.map((c) => c.id);
  room.turnIndex = 0;
  room.activeCharacterId = room.turnOrderQueue[0];
  const firstActiveChar = room.characters.find((c) => c.id === room.activeCharacterId);
  room.activePlayerId = firstActiveChar?.ownerId || room.players[0].id;

  room.recentActionLog.push({
    id: `log_${Date.now()}`,
    text: `⚔️ Битва началась! Первый ход: ${firstActiveChar?.name} (${firstActiveChar?.ownerName})`,
    timestamp: Date.now(),
    color: '#38bdf8',
  });

  startTurnTimer(room);

  broadcastToRoom(room, {
    type: 'MATCH_STARTED',
    payload: { room: serializeRoomForClient(room) },
  });
}

function handleServerEndTurn(room: ServerPvpRoom, characterId: string) {
  if (room.status !== 'in_battle') return;

  const livingChars = room.characters.filter((c) => c.currentHp > 0);
  if (livingChars.length === 0) return;

  // Reset active character's AP and MP for next cycle
  const currentActive = room.characters.find((c) => c.id === room.activeCharacterId);
  if (currentActive) {
    currentActive.currentAp = currentActive.maxAp || 3;
    currentActive.currentMpPoints = currentActive.maxMpPoints || currentActive.speed || 5;
  }

  // Advance turn index to next living character
  let nextIdx = (room.turnIndex + 1) % room.turnOrderQueue.length;
  let attempts = 0;
  while (attempts < room.turnOrderQueue.length) {
    const nextCharId = room.turnOrderQueue[nextIdx];
    const nextChar = room.characters.find((c) => c.id === nextCharId && c.currentHp > 0);
    if (nextChar) {
      room.turnIndex = nextIdx;
      room.activeCharacterId = nextChar.id;
      room.activePlayerId = nextChar.ownerId;
      nextChar.currentAp = nextChar.maxAp || 3;
      nextChar.currentMpPoints = nextChar.maxMpPoints || nextChar.speed || 5;
      break;
    }
    nextIdx = (nextIdx + 1) % room.turnOrderQueue.length;
    attempts++;
  }

  if (room.turnIndex === 0) {
    room.roundNumber += 1;
  }
  room.turnNumber += 1;

  startTurnTimer(room);

  const activeChar = room.characters.find((c) => c.id === room.activeCharacterId);

  room.recentActionLog.push({
    id: `log_${Date.now()}`,
    text: `⏳ Ход переходит к: ${activeChar?.name} (${activeChar?.ownerName})`,
    timestamp: Date.now(),
    color: '#a855f7',
  });

  broadcastToRoom(room, {
    type: 'ROOM_UPDATED',
    payload: { room: serializeRoomForClient(room) },
  });
}

function checkMatchWinner(room: ServerPvpRoom): boolean {
  if (room.status !== 'in_battle') return false;

  const p1 = room.players[0];
  const p2 = room.players[1];
  if (!p1 || !p2) return false;

  const p1Living = room.characters.filter((c) => c.ownerId === p1.id && c.currentHp > 0);
  const p2Living = room.characters.filter((c) => c.ownerId === p2.id && c.currentHp > 0);

  if (p1Living.length === 0 || p2Living.length === 0) {
    room.status = 'finished';
    room.finishedAt = Date.now();
    if (room.turnTimer) {
      clearInterval(room.turnTimer);
      room.turnTimer = undefined;
    }

    const winner = p1Living.length > 0 ? p1 : p2;
    room.winnerPlayerId = winner.id;
    room.winnerName = winner.name;

    const rewards = {
      currency: 200,
      spins: 2,
      ratingDelta: 25,
    };

    room.recentActionLog.push({
      id: `log_${Date.now()}`,
      text: `🏆 Победитель матча: ${winner.name}! Награда: +200 Валюты, +2 Крутки!`,
      timestamp: Date.now(),
      color: '#fbbf24',
    });

    // Save match to historical records
    const matchRecord = {
      id: `match_${Date.now()}_${room.id}`,
      roomId: room.id,
      title: room.title,
      mode: room.mode,
      winnerId: winner.id,
      winnerName: winner.name,
      players: room.players.map((p) => ({
        id: p.id,
        name: p.name,
        avatarUrl: p.avatarUrl,
        isWinner: p.id === winner.id,
      })),
      totalTurns: room.turnNumber,
      totalRounds: room.roundNumber,
      durationMs: (room.finishedAt || Date.now()) - (room.startedAt || room.createdAt),
      createdAt: Date.now(),
    };

    const history = loadMatchHistory();
    history.unshift(matchRecord);
    if (history.length > 50) history.pop();
    saveMatchHistory(history);

    broadcastToRoom(room, {
      type: 'MATCH_FINISHED',
      payload: {
        room: serializeRoomForClient(room),
        winnerId: winner.id,
        winnerName: winner.name,
        rewards,
      },
    });

    return true;
  }
  return false;
}

// ==========================================
// VITE / STATIC & SERVER BOOTSTRAP
// ==========================================
async function startServer() {
  const server = http.createServer(app);

  // Attach WebSocket server to the HTTP instance
  const wss = new WebSocketServer({ server });

  wss.on('connection', (ws: ExtendedWebSocket) => {
    ws.isAlive = true;

    ws.on('pong', () => {
      ws.isAlive = true;
    });

    ws.on('message', (data: string) => {
      try {
        const msg = JSON.parse(data.toString());
        const { type, payload } = msg;

        // Auto-extract user identity from message payload if provided
        if (payload?.user?.id) {
          ws.userId = payload.user.id;
          ws.userName = payload.user.name || ws.userName;
          ws.userAvatar = payload.user.avatarUrl || ws.userAvatar;
        } else if (payload?.userId) {
          ws.userId = payload.userId;
        }

        if (type === 'PING') {
          ws.send(JSON.stringify({ type: 'PONG' }));
          return;
        }

        if (type === 'IDENTIFY') {
          ws.userId = payload.userId;
          ws.userName = payload.userName;
          ws.userAvatar = payload.userAvatar;
          return;
        }

        if (type === 'GET_ROOMS') {
          broadcastRoomsList(ws);
          return;
        }

        if (type === 'CREATE_ROOM') {
          const { title, mode, characterIds = [], charactersData = [] } = payload;
          const pId = payload.user?.id || ws.userId || `user_${Date.now()}`;
          const pName = payload.user?.name || ws.userName || 'Игрок 1';
          const pAvatar = payload.user?.avatarUrl || ws.userAvatar || '';
          ws.userId = pId;
          ws.userName = pName;
          ws.userAvatar = pAvatar;

          const roomId = `room_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
          const newRoom: ServerPvpRoom = {
            id: roomId,
            title: title?.trim() || `Дуэль Разлома #${Math.floor(Math.random() * 900 + 100)}`,
            mode: mode === '3vs3' ? '3vs3' : '1vs1',
            status: 'waiting',
            maxPlayers: 2,
            players: [
              {
                id: pId,
                name: pName,
                avatarUrl: pAvatar,
                isHost: true,
                isReady: false,
                selectedCharacterIds: characterIds,
                charactersData: charactersData,
                faction: 'player',
                color: '#38bdf8',
                ws: ws,
              },
            ],
            mapId: 'pvp_arena_default',
            mapWidth: 24,
            mapHeight: 24,
            tiles: {},
            obstacles: {},
            characters: [],
            turnOrderQueue: [],
            turnIndex: 0,
            turnNumber: 0,
            roundNumber: 0,
            turnTimeRemaining: 45,
            turnTimeMax: 45,
            createdAt: Date.now(),
            recentActionLog: [
              {
                id: `log_${Date.now()}`,
                text: `Комната «${title || 'Дуэль'}» создана. Ожидание соперника...`,
                timestamp: Date.now(),
                color: '#94a3b8',
              },
            ],
          };

          pvpRooms.set(roomId, newRoom);
          ws.roomId = roomId;

          ws.send(
            JSON.stringify({
              type: 'ROOM_JOINED',
              payload: { room: serializeRoomForClient(newRoom), playerId: ws.userId },
            })
          );

          // Update lobby room lists
          wss.clients.forEach((client) => {
            if (client.readyState === WebSocket.OPEN) {
              broadcastRoomsList(client);
            }
          });
          return;
        }

        if (type === 'JOIN_ROOM') {
          const { roomId, characterIds = [], charactersData = [] } = payload;
          const pId = payload.user?.id || ws.userId || `user_${Date.now()}`;
          const pName = payload.user?.name || ws.userName || 'Игрок 2';
          const pAvatar = payload.user?.avatarUrl || ws.userAvatar || '';
          ws.userId = pId;
          ws.userName = pName;
          ws.userAvatar = pAvatar;

          const room = pvpRooms.get(roomId);
          if (!room) {
            ws.send(JSON.stringify({ type: 'ERROR', payload: { message: 'Комната не найдена' } }));
            return;
          }

          if (room.players.length >= room.maxPlayers && !room.players.some((p) => p.id === pId || p.ws === ws)) {
            ws.send(JSON.stringify({ type: 'ERROR', payload: { message: 'Комната уже заполнена' } }));
            return;
          }

          const existingPlayer = room.players.find((p) => p.id === pId || p.ws === ws);
          if (existingPlayer) {
            existingPlayer.id = pId;
            existingPlayer.name = pName;
            existingPlayer.avatarUrl = pAvatar;
            existingPlayer.ws = ws;
            existingPlayer.selectedCharacterIds = characterIds.length > 0 ? characterIds : existingPlayer.selectedCharacterIds;
            existingPlayer.charactersData = charactersData.length > 0 ? charactersData : existingPlayer.charactersData;
          } else {
            room.players.push({
              id: pId,
              name: pName,
              avatarUrl: pAvatar,
              isHost: false,
              isReady: false,
              selectedCharacterIds: characterIds,
              charactersData: charactersData,
              faction: 'enemy',
              color: '#f43f5e',
              ws: ws,
            });
          }

          ws.roomId = roomId;

          room.recentActionLog.push({
            id: `log_${Date.now()}`,
            text: `Игрок ${pName} присоединился к комнате.`,
            timestamp: Date.now(),
            color: '#34d399',
          });

          broadcastToRoom(room, {
            type: 'ROOM_UPDATED',
            payload: { room: serializeRoomForClient(room) },
          });

          ws.send(
            JSON.stringify({
              type: 'ROOM_JOINED',
              payload: { room: serializeRoomForClient(room), playerId: ws.userId },
            })
          );
          return;
        }

        if (type === 'SELECT_CHARACTERS') {
          const { roomId, characterIds, charactersData } = payload;
          const pId = payload.userId || ws.userId;
          const room = pvpRooms.get(roomId);
          if (!room) return;

          const player = room.players.find((p) => p.id === pId || p.ws === ws);
          if (player) {
            const limitCount = room.mode === '1vs1' ? 1 : 3;
            player.selectedCharacterIds = Array.isArray(characterIds) ? characterIds.slice(0, limitCount) : [];
            player.charactersData = Array.isArray(charactersData) ? charactersData.slice(0, limitCount) : [];

            broadcastToRoom(room, {
              type: 'ROOM_UPDATED',
              payload: { room: serializeRoomForClient(room) },
            });
          }
          return;
        }

        if (type === 'SET_READY') {
          const { roomId, isReady } = payload;
          const pId = payload.userId || ws.userId;
          const room = pvpRooms.get(roomId);
          if (!room) return;

          const player = room.players.find((p) => p.id === pId || p.ws === ws);
          if (player) {
            player.isReady = Boolean(isReady);

            broadcastToRoom(room, {
              type: 'ROOM_UPDATED',
              payload: { room: serializeRoomForClient(room) },
            });

            // If all players are ready and 2 players are in the room, start match automatically!
            if (
              room.players.length === room.maxPlayers &&
              room.players.every((p) => p.isReady && p.selectedCharacterIds.length > 0)
            ) {
              startMatchInRoom(room);
            }
          }
          return;
        }

        if (type === 'START_MATCH') {
          const { roomId } = payload;
          const pId = payload.userId || ws.userId;
          const room = pvpRooms.get(roomId);
          if (!room) return;

          const player = room.players.find((p) => p.id === pId || p.ws === ws);
          if (player && player.isHost && room.players.length === room.maxPlayers) {
            startMatchInRoom(room);
          }
          return;
        }

        if (type === 'ACTION_MOVE') {
          const { roomId, characterId, targetX, targetY, path: movePath } = payload;
          const room = pvpRooms.get(roomId);
          if (!room || room.status !== 'in_battle') return;

          const char = room.characters.find((c) => c.id === characterId);
          if (!char) return;

          // STRICT OWNERSHIP & TURN CHECK: Player can ONLY control their own character!
          if (char.ownerId !== ws.userId) {
            ws.send(JSON.stringify({ type: 'ERROR', payload: { message: 'Вы не можете управлять чужим персонажем!' } }));
            return;
          }

          if (room.activeCharacterId !== char.id) {
            ws.send(JSON.stringify({ type: 'ERROR', payload: { message: 'Сейчас не ход этого персонажа!' } }));
            return;
          }

          const stepsCount = Array.isArray(movePath) ? movePath.length - 1 : Math.abs(targetX - char.x) + Math.abs(targetY - char.y);
          const currentMp = char.currentMpPoints ?? char.speed ?? 5;

          if (stepsCount > currentMp || stepsCount <= 0) {
            ws.send(JSON.stringify({ type: 'ERROR', payload: { message: 'Недостаточно очков передвижения!' } }));
            return;
          }

          // Update position
          const oldX = char.x;
          const oldY = char.y;
          char.x = targetX;
          char.y = targetY;
          char.facing = targetX > oldX ? 'right' : targetX < oldX ? 'left' : char.facing;
          char.currentMpPoints = Math.max(0, currentMp - stepsCount);

          // Broadcast instant animation event
          broadcastToRoom(room, {
            type: 'ANIMATION_EVENT',
            payload: {
              id: `anim_${Date.now()}_${Math.random()}`,
              type: 'move',
              sourceCharacterId: char.id,
              targetPos: { x: targetX, y: targetY },
              path: movePath,
              timestamp: Date.now(),
            },
          });

          room.recentActionLog.push({
            id: `log_${Date.now()}`,
            text: `🏃 ${char.name} переместился на клетку (${targetX}, ${targetY}) [-${stepsCount} ОП]`,
            timestamp: Date.now(),
            color: '#60a5fa',
          });

          broadcastToRoom(room, {
            type: 'ROOM_UPDATED',
            payload: { room: serializeRoomForClient(room) },
          });
          return;
        }

        if (type === 'ACTION_ATTACK') {
          const { roomId, characterId, targetCharacterId } = payload;
          const room = pvpRooms.get(roomId);
          if (!room || room.status !== 'in_battle') return;

          const actor = room.characters.find((c) => c.id === characterId);
          const target = room.characters.find((c) => c.id === targetCharacterId);
          if (!actor || !target) return;

          if (actor.ownerId !== ws.userId) {
            ws.send(JSON.stringify({ type: 'ERROR', payload: { message: 'Вы можете отдавать приказы только своим бойцам!' } }));
            return;
          }

          if (room.activeCharacterId !== actor.id) {
            ws.send(JSON.stringify({ type: 'ERROR', payload: { message: 'Сейчас не ход вашего персонажа!' } }));
            return;
          }

          const currentAp = actor.currentAp ?? actor.maxAp ?? 3;
          if (currentAp < 1) {
            ws.send(JSON.stringify({ type: 'ERROR', payload: { message: 'Недостаточно очков действия (ОД)!' } }));
            return;
          }

          const dist = Math.abs(actor.x - target.x) + Math.abs(actor.y - target.y);
          if (dist > 1) {
            ws.send(JSON.stringify({ type: 'ERROR', payload: { message: 'Цель вне радиуса ближней атаки!' } }));
            return;
          }

          // Compute damage
          actor.currentAp = Math.max(0, currentAp - 1);
          const baseAtk = Number(actor.stats?.baseAttack || 75);
          const targetArmor = Number(target.stats?.armor || target.stats?.defense || 40);
          const critChance = Number(actor.stats?.critChance || 5);
          const isCrit = Math.random() * 100 < critChance;
          const multiplier = isCrit ? 1.5 : 1.0;
          const mitigation = 100 / (100 + targetArmor);
          const rawDamage = Math.round(baseAtk * multiplier * mitigation);
          const damage = Math.max(5, rawDamage);

          target.currentHp = Math.max(0, target.currentHp - damage);

          // Broadcast combat animation
          broadcastToRoom(room, {
            type: 'ANIMATION_EVENT',
            payload: {
              id: `anim_${Date.now()}_${Math.random()}`,
              type: 'attack',
              sourceCharacterId: actor.id,
              targetCharacterId: target.id,
              damage,
              isCrit,
              timestamp: Date.now(),
            },
          });

          room.recentActionLog.push({
            id: `log_${Date.now()}`,
            text: `⚔️ ${actor.name} нанес ${isCrit ? 'КРИТИЧЕСКИЙ ' : ''}${damage} урона по ${target.name}!`,
            timestamp: Date.now(),
            color: isCrit ? '#f59e0b' : '#ef4444',
          });

          if (target.currentHp <= 0) {
            room.recentActionLog.push({
              id: `log_${Date.now()}`,
              text: `💀 ${target.name} пал в бою!`,
              timestamp: Date.now(),
              color: '#dc2626',
            });
          }

          broadcastToRoom(room, {
            type: 'ROOM_UPDATED',
            payload: { room: serializeRoomForClient(room) },
          });

          checkMatchWinner(room);
          return;
        }

        if (type === 'ACTION_SKILL') {
          const { roomId, characterId, skillId, targetCharacterId, targetX, targetY } = payload;
          const room = pvpRooms.get(roomId);
          if (!room || room.status !== 'in_battle') return;

          const actor = room.characters.find((c) => c.id === characterId);
          if (!actor) return;

          if (actor.ownerId !== ws.userId) {
            ws.send(JSON.stringify({ type: 'ERROR', payload: { message: 'Вы не управляете этим персонажем!' } }));
            return;
          }

          if (room.activeCharacterId !== actor.id) {
            ws.send(JSON.stringify({ type: 'ERROR', payload: { message: 'Сейчас не ваш ход!' } }));
            return;
          }

          const skill = (actor.skills || []).find((s: any) => s.id === skillId) || actor.skills?.[0];
          if (!skill) return;

          const apCost = 1;
          const manaCost = Number(skill.manaCost || 10);
          const currentAp = actor.currentAp ?? 3;
          const currentMana = actor.currentMana ?? 60;

          if (currentAp < apCost) {
            ws.send(JSON.stringify({ type: 'ERROR', payload: { message: 'Недостаточно ОД для применения навыка!' } }));
            return;
          }
          if (currentMana < manaCost) {
            ws.send(JSON.stringify({ type: 'ERROR', payload: { message: 'Недостаточно маны!' } }));
            return;
          }

          actor.currentAp = Math.max(0, currentAp - apCost);
          actor.currentMana = Math.max(0, currentMana - manaCost);

          const target = targetCharacterId ? room.characters.find((c) => c.id === targetCharacterId) : null;
          let damage = 0;
          let heal = 0;

          if (skill.type === 'heal' || skill.name?.toLowerCase().includes('исцеление') || skill.name?.toLowerCase().includes('лечение')) {
            const intVal = Number(actor.stats?.intellect || actor.stats?.magic || 50);
            heal = Math.round(intVal * 1.5 + 30);
            if (target) {
              target.currentHp = Math.min(target.maxHp, target.currentHp + heal);
            } else {
              actor.currentHp = Math.min(actor.maxHp, actor.currentHp + heal);
            }

            broadcastToRoom(room, {
              type: 'ANIMATION_EVENT',
              payload: {
                id: `anim_${Date.now()}_${Math.random()}`,
                type: 'heal',
                sourceCharacterId: actor.id,
                targetCharacterId: target?.id || actor.id,
                heal,
                skillName: skill.name,
                skillEffectColor: '#10b981',
                timestamp: Date.now(),
              },
            });

            room.recentActionLog.push({
              id: `log_${Date.now()}`,
              text: `✨ ${actor.name} использовал «${skill.name}» и восстановил ${heal} HP!`,
              timestamp: Date.now(),
              color: '#10b981',
            });
          } else {
            // Offensive skill
            const baseAtk = Number(actor.stats?.baseAttack || actor.stats?.magic || 75);
            const targetArmor = Number(target?.stats?.magicArmor || target?.stats?.armor || 30);
            const rawDmg = Math.round(baseAtk * 1.4 * (100 / (100 + targetArmor)));
            damage = Math.max(10, rawDmg);

            if (target) {
              target.currentHp = Math.max(0, target.currentHp - damage);
            }

            broadcastToRoom(room, {
              type: 'ANIMATION_EVENT',
              payload: {
                id: `anim_${Date.now()}_${Math.random()}`,
                type: 'skill_impact',
                sourceCharacterId: actor.id,
                targetCharacterId: target?.id,
                targetPos: target ? { x: target.x, y: target.y } : (targetX !== undefined ? { x: targetX, y: targetY || 0 } : undefined),
                damage,
                skillName: skill.name,
                skillEffectColor: '#f97316',
                timestamp: Date.now(),
              },
            });

            room.recentActionLog.push({
              id: `log_${Date.now()}`,
              text: `🔥 ${actor.name} обрушил «${skill.name}» на ${target?.name || 'область'} [${damage} урона]!`,
              timestamp: Date.now(),
              color: '#f97316',
            });
          }

          broadcastToRoom(room, {
            type: 'ROOM_UPDATED',
            payload: { room: serializeRoomForClient(room) },
          });

          checkMatchWinner(room);
          return;
        }

        if (type === 'ACTION_DEFEND') {
          const { roomId, characterId } = payload;
          const room = pvpRooms.get(roomId);
          if (!room || room.status !== 'in_battle') return;

          const actor = room.characters.find((c) => c.id === characterId);
          if (!actor || actor.ownerId !== ws.userId) return;

          actor.currentAp = 0;
          actor.isDefending = true;

          broadcastToRoom(room, {
            type: 'ANIMATION_EVENT',
            payload: {
              id: `anim_${Date.now()}_${Math.random()}`,
              type: 'defend',
              sourceCharacterId: actor.id,
              timestamp: Date.now(),
            },
          });

          room.recentActionLog.push({
            id: `log_${Date.now()}`,
            text: `🛡️ ${actor.name} встал в глухую оборону (+50% защиты).`,
            timestamp: Date.now(),
            color: '#38bdf8',
          });

          handleServerEndTurn(room, characterId);
          return;
        }

        if (type === 'ACTION_END_TURN') {
          const { roomId, characterId } = payload;
          const room = pvpRooms.get(roomId);
          if (!room || room.status !== 'in_battle') return;

          const actor = room.characters.find((c) => c.id === characterId);
          if (actor && actor.ownerId === ws.userId) {
            handleServerEndTurn(room, characterId);
          }
          return;
        }

        if (type === 'SEND_CHAT') {
          const { roomId, text } = payload;
          const room = pvpRooms.get(roomId);
          if (!room || !text || !text.trim()) return;

          const chatMsg = {
            id: `chat_${Date.now()}_${Math.random()}`,
            senderId: ws.userId || 'anon',
            senderName: ws.userName || 'Боец',
            senderAvatar: ws.userAvatar || '',
            text: text.trim(),
            timestamp: Date.now(),
          };

          broadcastToRoom(room, {
            type: 'CHAT_BROADCAST',
            payload: chatMsg,
          });
          return;
        }

        if (type === 'SURRENDER') {
          const { roomId } = payload;
          const room = pvpRooms.get(roomId);
          if (!room || room.status !== 'in_battle') return;

          const otherPlayer = room.players.find((p) => p.id !== ws.userId);
          if (otherPlayer) {
            room.status = 'finished';
            room.finishedAt = Date.now();
            room.winnerPlayerId = otherPlayer.id;
            room.winnerName = otherPlayer.name;

            if (room.turnTimer) {
              clearInterval(room.turnTimer);
              room.turnTimer = undefined;
            }

            broadcastToRoom(room, {
              type: 'MATCH_FINISHED',
              payload: {
                room: serializeRoomForClient(room),
                winnerId: otherPlayer.id,
                winnerName: otherPlayer.name,
                rewards: { currency: 150, spins: 1, ratingDelta: 20 },
              },
            });
          }
          return;
        }

        if (type === 'LEAVE_ROOM') {
          const { roomId } = payload;
          const pId = payload.userId || ws.userId;
          const room = pvpRooms.get(roomId);
          if (room) {
            room.players = room.players.filter((p) => p.id !== pId && p.ws !== ws);
            if (room.players.length === 0) {
              if (room.turnTimer) clearInterval(room.turnTimer);
              pvpRooms.delete(roomId);
            } else {
              broadcastToRoom(room, {
                type: 'ROOM_UPDATED',
                payload: { room: serializeRoomForClient(room) },
              });
            }
          }
          ws.send(JSON.stringify({ type: 'ROOM_LEFT', payload: { roomId } }));
          wss.clients.forEach((client) => {
            if (client.readyState === WebSocket.OPEN) {
              broadcastRoomsList(client);
            }
          });
          return;
        }
      } catch (err) {
        console.error('Error processing WS message:', err);
      }
    });

    ws.on('close', () => {
      if (ws.roomId) {
        const room = pvpRooms.get(ws.roomId);
        if (room) {
          const player = room.players.find((p) => p.id === ws.userId);
          if (player) {
            player.ws = undefined;
          }
          if (room.players.every((p) => !p.ws)) {
            if (room.turnTimer) clearInterval(room.turnTimer);
            pvpRooms.delete(ws.roomId);
          }
        }
      }
    });
  });

  // Heartbeat interval for stale WS detection
  setInterval(() => {
    wss.clients.forEach((ws: any) => {
      if (ws.isAlive === false) return ws.terminate();
      ws.isAlive = false;
      ws.ping();
    });
  }, 30000);

  // Vite or Static file serving
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  server.listen(PORT, '0.0.0.0', () => {
    console.log(`Server + WebSocket running on port ${PORT}`);
  });
}

startServer();
